		string[] names = new string[symbolInfos.size()];
		int i = 0;
		foreach (SymbolInfo symbolInfo in symbolInfos) {
			names[i++] = symbolInfo.getName();
		}
		return names;
	}

	public bool contains(Symbol symbol) {
